using System.Security.Cryptography;

namespace mk8.email.Configuration;

/// <summary>One explicitly provisioned, portable admin-cookie key; never generated by service startup.</summary>
public sealed class DataProtectionKeyConfig
{
    public Guid Id { get; init; }
    public DateTimeOffset CreatedAt { get; init; }
    public DateTimeOffset ActivatesAt { get; init; }
    public DateTimeOffset ExpiresAt { get; init; }
    public DateTimeOffset? RevokedAt { get; init; }
    public string MasterKey { get; init; } = string.Empty;

    internal static void ValidateKeys(IReadOnlyList<DataProtectionKeyConfig> keys)
    {
        ArgumentNullException.ThrowIfNull(keys);
        if (keys.Count is < 1 or > 64 || keys.Any(key => key is null)
            || keys.Select(key => key.Id).ToHashSet().Count != keys.Count)
        {
            throw new InvalidOperationException("The admin-cookie snapshot requires from one through 64 distinct keys.");
        }
        var now = DateTimeOffset.UtcNow;
        if (!keys.Any(key => key.RevokedAt is null && key.ActivatesAt <= now && now < key.ExpiresAt))
            throw new InvalidOperationException("The admin-cookie snapshot has no currently active non-revoked key.");
        foreach (var key in keys)
        {
            var bytes = key.DecodeMasterKey();
            CryptographicOperations.ZeroMemory(bytes);
        }
    }

    /// <summary>Returns independently owned key bytes; the caller must clear them after use.</summary>
    public byte[] DecodeMasterKey()
    {
        if (Id == Guid.Empty || CreatedAt == default || ActivatesAt < CreatedAt || ExpiresAt <= ActivatesAt
            || RevokedAt < CreatedAt || RevokedAt > DateTimeOffset.UtcNow)
        {
            throw new InvalidOperationException("The admin-cookie key identity or lifetime is invalid.");
        }
        if (MasterKey is null || MasterKey.Length != 88)
            throw new InvalidOperationException("An admin-cookie key requires canonical base64 for a 512-bit master key.");
        byte[] bytes;
        try { bytes = Convert.FromBase64String(MasterKey); }
        catch (FormatException)
        {
            throw new InvalidOperationException("An admin-cookie key requires canonical base64 for a 512-bit master key.");
        }
        if (bytes.Length == 64 && string.Equals(Convert.ToBase64String(bytes), MasterKey, StringComparison.Ordinal))
            return bytes;
        CryptographicOperations.ZeroMemory(bytes);
        throw new InvalidOperationException("An admin-cookie key requires canonical base64 for a 512-bit master key.");
    }
}
